import { useEffect, useRef } from "react";
import {gsap} from "gsap";
import {ScrollTrigger} from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

function Profile() {
    
    // .line 요소 참조를 위한 ref
    const lineRef = useRef(null);

    useEffect(() => {
        const path = lineRef.current.querySelector(".cls-1"); // SVG 경로 선택
        const length = path.getTotalLength(); // SVG 경로의 전체 길이 계산
    
        // 초기 상태: 선이 보이지 않도록 설정
        gsap.set(path, {
          strokeDasharray: length,
          strokeDashoffset: length,
        });
    
        // 애니메이션 정의
        const drawLine = () => {
          gsap.fromTo(
            path,
            { strokeDashoffset: length }, // 시작: 선이 숨겨짐
            { strokeDashoffset: 0, duration: 1, ease: "power2.out" } // 끝: 선이 나타남
          );
        };
    
        // ScrollTrigger 설정
        ScrollTrigger.create({
          trigger: lineRef.current, // 트리거 요소
          start: "top 80%", // 요소가 뷰포트 80% 지점에 닿을 때 시작
          end: "top 20%", // 요소가 뷰포트 20% 지점에 닿을 때 종료
          onEnter: () => drawLine(), // 스크롤 내려서 영역 진입 시 애니메이션 실행
          onEnterBack: () => drawLine(), // 스크롤 올려서 영역 재진입 시 애니메이션 실행
          // markers: true, // 디버깅용 마커 (필요 시 주석 해제)
        });
    
        // 클린업: 컴포넌트 언마운트 시 ScrollTrigger 제거
        return () => {
          ScrollTrigger.getAll().forEach((trigger) => trigger.kill());
        };
      }, []);

      
    return (
        <div id="profile" className="profile">
            <div className="profile_h">
                <p className="title">Profile</p>
                <div className="line" ref={lineRef}>
                    <svg id="Layer_6" data-name="Layer 1" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1060.26 100.5">
                        <path class="cls-1" d="m.37,50.25c94.67-37.17,336-89.2,542,0,206,89.2,430.67,37.17,517.5,0" />
                    </svg>
                </div>
            </div>
            <div className="profile_i">
                <div className="main_info">
                    <figure className="profile_img">
                        <img src="./img/profile.jpg" className="profile_img" alt="profile img" />
                    </figure>
                    <div className="name">
                        <p className="name_kr">구 경희</p>
                        <p className="name_eng">Koo KyeongHee</p>
                    </div>
                    <div className="main_info_detail">
                        <div className="personal_info">
                            <p className="birth">1998.10.14</p>
                            <p className="mail">watchee9@gmail.com</p>
                        </div>
                        <div className="resume">
                            <a href="#">
                                <p>Resume</p>
                                <svg id="Layer_7" data-name="Layer 1" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20">
                                    <circle class="cls-2" cx="10" cy="10" r="10" />
                                    <path class="cls-1" d="m17.19,11.36l-11.04,5.66c-.56.29-1.22-.12-1.22-.75h0c0-.32.18-.61.46-.75l10.33-5.14v-.05L5.4,5.2c-.28-.14-.46-.43-.46-.75h0c0-.63.66-1.03,1.22-.75l11.04,5.66c.28.14.46.43.46.75v.51c0,.31-.18.6-.46.75Z" />
                                </svg>
                            </a>
                        </div>
                    </div>
                </div>
                <div className="sub_info">
                    <div className="sub_info_i">
                        <div className="info_1">
                            <div className="edu">
                                <p className="sub_info_tit">Education</p>
                                <div className="edu_info">
                                    <div className="edu_info_detail">
                                        <p>계명대학교 졸업</p>
                                    </div>
                                    <div className="edu_info_detail">
                                        <p>동대학원 석사 수료</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div className="info_2">
                            <div className="certi">
                                <p className="sub_info_tit">Certificate</p>
                                <div className="certi_info">
                                    <div className="certi_info_detail">
                                        <p>운전면허 1종 보통</p>
                                    </div>
                                    {/* <div className="certi_info_detail">
                                        <p>웹디자인개발기능사</p>
                                    </div> */}
                                    <div className="certi_info_detail">
                                        <p>ACP Photoshop</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div className="info_3">
                        <div className="skills">
                            <p className="sub_info_tit">Skills</p>
                            <div className="skills_info">
                                <div className="skills_info_detail">
                                    <p className="skills_tit">Html</p>
                                    <div className="skill_chart">
                                        <svg className="chart" width="380" height="12" viewBox="0 0 380 12" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <rect width="380" height="12" fill="#FD6D24" />
                                        </svg>
                                    </div>
                                    <p className="percent">100%</p>
                                </div>
                                <div className="skills_info_detail">
                                    <p className="skills_tit">Css</p>
                                    <div className="skill_chart">
                                        <svg className="chart" width="380" height="12" viewBox="0 0 380 12" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <rect width="380" height="12" fill="#225AB9" />
                                            <rect width="370" height="12" fill="#FD6D24" />
                                        </svg>
                                    </div>
                                    <p className="percent">90%</p>
                                </div>
                                <div className="skills_info_detail">
                                    <p className="skills_tit">Javascript</p>
                                    <div className="skill_chart">
                                        <svg className="chart" width="380" height="12" viewBox="0 0 380 12" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <rect width="380" height="12" fill="#225AB9" />
                                            <rect width="360" height="12" fill="#FD6D24" />
                                        </svg>

                                    </div>
                                    <p className="percent">80%</p>
                                </div>
                                <div className="skills_info_detail">
                                    <p className="skills_tit">React</p>
                                    <div className="skill_chart">
                                        <svg className="chart" width="380" height="12" viewBox="0 0 380 12" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <rect width="380" height="12" fill="#225AB9" />
                                            <rect width="360" height="12" fill="#FD6D24" />
                                        </svg>
                                    </div>
                                    <p className="percent">80%</p>
                                </div>
                                <div className="skills_info_detail">
                                    <p className="skills_tit">React-Query</p>
                                    <div className="skill_chart">
                                        <svg className="chart" width="380" height="12" viewBox="0 0 380 12" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <rect width="380" height="12" fill="#225AB9" />
                                            <rect width="360" height="12" fill="#FD6D24" />
                                        </svg>
                                    </div>
                                    <p className="percent">80%</p>
                                </div>
                                <div className="skills_info_detail">
                                    <p className="skills_tit">React-Redux</p>
                                    <div className="skill_chart">
                                        <svg className="chart" width="380" height="12" viewBox="0 0 380 12" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <rect width="380" height="12" fill="#225AB9" />
                                            <rect width="360" height="12" fill="#FD6D24" />
                                        </svg>
                                    </div>
                                    <p className="percent">80%</p>
                                </div>
                                <div className="skills_info_detail">
                                    <p className="skills_tit">Photoshop</p>
                                    <div className="skill_chart">
                                        <svg className="chart" width="380" height="12" viewBox="0 0 380 12" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <rect width="380" height="12" fill="#225AB9" />
                                            <rect width="370" height="12" fill="#FD6D24" />
                                        </svg>
                                    </div>
                                    <p className="percent">90%</p>
                                </div>
                                <div className="skills_info_detail">
                                    <p className="skills_tit">Illustrator</p>
                                    <div className="skill_chart">
                                        <svg className="chart" width="380" height="12" viewBox="0 0 380 12" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <rect width="380" height="12" fill="#225AB9" />
                                            <rect width="370" height="12" fill="#FD6D24" />
                                        </svg>
                                    </div>
                                    <p className="percent">90%</p>
                                </div>
                                <div className="skills_info_detail">
                                    <p className="skills_tit">Figma</p>
                                    <div className="skill_chart">
                                        <svg className="chart" width="380" height="12" viewBox="0 0 380 12" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <rect width="380" height="12" fill="#225AB9" />
                                            <rect width="360" height="12" fill="#FD6D24" />
                                        </svg>
                                    </div>
                                    <p className="percent">80%</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default Profile;