import { useEffect, useRef } from "react";

function Contact() {

    const lineRefPC = useRef(null);   // Layer_10
    const lineRefMo = useRef(null);   // Layer_11

    useEffect(() => {
        const observer = new IntersectionObserver(
            (entries) => {
                entries.forEach((entry) => {
                    if (entry.isIntersecting) {
                        if (window.innerWidth >= 1368 && lineRefPC.current) {
                            lineRefPC.current.classList.add("contact_h_line_active");
                        }
                        if (window.innerWidth < 1368 && lineRefMo.current) {
                            lineRefMo.current.classList.add("contact_h_line_active");
                        }
                    }
                });
            },
            { threshold: 0.5 }
        );

        const contactSection = document.querySelector('#contact');
        if (contactSection) observer.observe(contactSection);

        return () => observer.disconnect();
    }, []);


    return (
        <div id="contact" className="contact">
            <div className="contact_h">
                <div className="contact_h_line" ref={lineRefPC}>
                    <svg id="Layer_10" data-name="Layer 1" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1096.48 66.01">
                        <path className="cls-1" d="M0.26,35.54C397.26,141.22,593.76-80.28,1096.26,35.54" />
                    </svg>
                </div>
                <p className="title">Contact</p>
                <div className="contact_h_line_mo" ref={lineRefMo}>
                    <svg id="Layer_11" data-name="Layer 1" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1096.48 66.01">
                        <path className="cls-1" d="m1096.26,35.54C593.76-80.28,397.26,141.22.26,35.54" />
                    </svg>
                </div>
            </div>
            <div className="contact_i">
                <div className="gratitude">
                    <div className="bg">
                        <img className="background_img" src="./img/contact.svg" alt="background image" />
                    </div>
                    <p className="thank">Thank</p>
                    <p className="you">you</p>
                </div>
                <div className="contact_box">
                    <h3 className="contact_me">Contact Me</h3>
                    <div className="contact_box_i">
                        <div className="contact_info1">
                            <div className="mail">
                                <img src="./img/mail.svg" alt="e-mail icon" />
                            </div>
                            <p className="email">watchee9@gmail.com</p>
                        </div>
                        <div className="contact_info2">
                            <div className="phone">
                                <img src="./img/phone.svg" alt="phone-call icon" />
                            </div>
                            <p className="phone_num">010-5417-9377</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default Contact;