import { useEffect, useRef } from "react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

function Project() {
  const rightLineRef = useRef(null); // PC용 오른쪽 라인
  const leftLineMoRef = useRef(null); // 왼쪽 라인 (PC + 모바일 모두 사용)

  useEffect(() => {
    // 왼쪽 선 애니메이션 (PC + 모바일)
    const leftPath = leftLineMoRef.current.querySelector(".cls-1");
    const leftLength = leftPath.getTotalLength();

    gsap.set(leftPath, {
      strokeDasharray: leftLength,
      strokeDashoffset: leftLength,
    });

    const drawLeftLine = () => {
      gsap.fromTo(
        leftPath,
        { strokeDashoffset: leftLength },
        { strokeDashoffset: 0, duration: 1, ease: "power2.out" }
      );
    };

    ScrollTrigger.create({
      trigger: leftLineMoRef.current,
      start: "top 80%",
      end: "top 20%",
      onEnter: () => drawLeftLine(),
      onEnterBack: () => drawLeftLine(),
    });

    // 오른쪽 선 애니메이션 (PC용, 1024px 이상에서만 작동)
    const rightPath = rightLineRef.current.querySelector(".cls-1");
    const rightLength = rightPath.getTotalLength();

    gsap.set(rightPath, {
      strokeDasharray: rightLength,
      strokeDashoffset: rightLength,
    });

    const drawRightLine = () => {
      gsap.fromTo(
        rightPath,
        { strokeDashoffset: rightLength },
        { strokeDashoffset: 0, duration: 1, ease: "power2.out" }
      );
    };

    let rightTrigger = null;

    // 오른쪽 선 ScrollTrigger를 동적으로 설정하는 함수
    const setupRightLineTrigger = () => {
      if (window.innerWidth >= 1024) {
        if (!rightTrigger || !rightTrigger.isActive()) {
          rightTrigger = ScrollTrigger.create({
            trigger: rightLineRef.current,
            start: "top 80%",
            end: "top 20%",
            onEnter: () => drawRightLine(),
            onEnterBack: () => drawRightLine(),
          });
        }
      } else if (rightTrigger) {
        rightTrigger.kill(); // 창 크기가 1024px 미만이면 트리거 제거
        rightTrigger = null;
      }
    };

    // 초기 설정
    setupRightLineTrigger();

    // 창 크기 변경 시 트리거 재설정
    const handleResize = () => {
      setupRightLineTrigger();
    };
    window.addEventListener("resize", handleResize);

    // 클린업
    return () => {
      window.removeEventListener("resize", handleResize);
      ScrollTrigger.getAll().forEach((trigger) => trigger.kill());
    };
  }, []);

  return (
    <div id="project" className="project">
      <div className="project_h">
        <div className="projeect_h_line_l" ref={leftLineMoRef}>
          <svg
            id="Layer_8"
            data-name="Layer 1"
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 422.37 44.41"
          >
            <path
              className="cls-1"
              d="m.4,22.2c36.33,16,131.1,38.4,219.5,0s171.5-16,202,0"
            />
          </svg>
        </div>
        <p className="title_1">Project</p>
        <div className="projeect_h_line_r" ref={rightLineRef}>
          <svg
            id="Layer_9"
            data-name="Isolation Mode"
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 940.42 84.33"
          >
            <path
              className="cls-1"
              d="m940.23,47.41c-81.03-15.85-227.99-96-477,0-187.34,72.22-394.98,15.85-463,0"
            />
          </svg>
        </div>
      </div>
      <div className="project_i">
        <div className="project_1">
          <div className="thumbnail">
            <div className="thumbnail_img project_float">
              <a href="https://kyeong-hee.github.io/clone/">
                <img src="./img/clonecoding.svg" alt="clonecoding_thumbnail" />
              </a>
            </div>
            <div className="desc">
              <h3 className="project_tit">CLONE CORDING</h3>
              <div className="visit">
                <a href="https://kyeong-hee.github.io/clone/">Visit Site</a>
              </div>
            </div>
          </div>
        </div>
        <div className="project_2">
          <div className="desc">
            <h3 className="project_tit">WEATHER APP</h3>
            <div className="visit">
              <a href="https://kyeong-hee.github.io/weather/">Visit Site</a>
            </div>
          </div>
          <div className="thumbnail">
            <div className="thumbnail_img project_float_up">
              <a href="https://kyeong-hee.github.io/weather/">
                <img src="./img/weather.svg" alt="weatherapp_thumbnail" />
              </a>
            </div>
          </div>
        </div>
        <div className="project_3">
          <div className="thumbnail">
            <div className="thumbnail_img project_float">
              <a href="https://kyeong-hee.github.io/allofyour/">
                <img src="./img/clone2.svg" alt="thumbnail" />
              </a>
            </div>
          </div>
          <div className="desc">
            <h3 className="project_tit">CLONE CORDING</h3>
            <div className="visit">
              <a href="https://kyeong-hee.github.io/allofyour/">Vist Site</a>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Project;